use crate::{mswm03 as m,model::*,unit_support::*,catalog,deck};
use crate::jc029_tests::pass_top;
fn setup()->(Game,String,String){let mut g=game();let s=g.make_card(m::ID,0);let id=s.id.clone();g.players[0].society_zone.card=Some(s);fund(&mut g,0,"JC125",3);let criminal=field(&mut g,"JC084",0);(g,id,criminal)}
fn action(id:&str,hand:&str,c:&str)->Action{Action{card_id:Some(id.into()),ability_id:Some(m::KEY.into()),cost_selected:Some(vec![hand.into(),c.into()]),..Action::new("activate")}}
#[test]fn mswm03_paid_criminal_or_noncriminal_draws_and_only_actual_paid_criminal_hides(){for discarded in ["JC125","WM063"]{let(mut g,id,c)=setup();let other=field(&mut g,"JC084",0);let h=held(&mut g,discarded,0);let n=g.players[0].hand.len();act(&mut g,0,action(&id,&h,&c));assert_eq!(g.resources(0),1);assert!(g.board(&c).unwrap().1.exhausted);pass_top(&mut g);assert_eq!(g.players[0].hand.len(),n);assert!(g.players[0].society_zone.card.as_ref().unwrap().exhausted);assert!(!g.board(&other).unwrap().1.face_down);if discarded=="WM063"{assert!(g.board(&c).is_none());assert!(g.regions[0].cards.iter().any(|c|c.face_down&&c.exhausted));}else{assert!(!g.board(&c).unwrap().1.face_down);}restore(&mut g);}}
#[test]fn mswm03_bad_payment_extra_payload_and_corrupt_frames_rejected(){let(mut g,id,c)=setup();let h=held(&mut g,"WM063",0);let other=field(&mut g,"JC084",1);for ids in [vec![h.clone()],vec![h.clone(),h.clone()],vec![c.clone(),h.clone()],vec![h.clone(),other]]{let mut a=action(&id,&h,&c);a.cost_selected=Some(ids);reject(&mut g,0,a);}let mut a=action(&id,&h,&c);a.target_id=Some(c.clone());reject(&mut g,0,a);act(&mut g,0,action(&id,&h,&c));for n in 0..6{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.already_paid.clear(),1=>f.source.card.definition="MSJC09".into(),2=>f.actor=1,3=>f.steps.clear(),4=>if let PaidCost::MSWM03Payment(p)=&mut f.already_paid[2]{p.criminal.card.exhausted=true;},_=>if let PaidCost::MSWM03Payment(p)=&mut f.already_paid[2]{p.discarded_subtypes.clear();}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}pass_top(&mut g);}
#[test]fn mswm03_response_departure_never_substitutes_another_criminal(){let(mut g,id,c)=setup();let h=held(&mut g,"WM063",0);let other=field(&mut g,"JC084",0);act(&mut g,0,action(&id,&h,&c));g.remove_dead(&c,RemovalCause::Destroy);g.drive().unwrap();pass_top(&mut g);assert!(!g.board(&other).unwrap().1.face_down);restore(&mut g);}
fn draft(markets:usize)->deck::DeckDraft{let mut d=deck::preset("watchers").unwrap();d.id="closed-cold-mountain".into();d.society_id=Some(m::ID.into());d.core_card_id=None;d.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:41-markets},catalog::DeckEntry{card_id:"JC084".into(),count:3},catalog::DeckEntry{card_id:"WM057".into(),count:3},catalog::DeckEntry{card_id:"JC102".into(),count:3}];if markets>0{d.cards.push(catalog::DeckEntry{card_id:"WM063".into(),count:markets});}d}
fn validated(d:deck::DeckDraft)->Result<deck::DeckDraft,String>{let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id=="WM063").unwrap().supported=true;let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==m::ID).unwrap().card.supported=true;deck::validate_with_registry(d,&cards,&societies)}
fn constructed(seed:u64,markets:usize)->(Game,deck::DeckDraft){let d=validated(draft(markets)).unwrap();let mut other=d.clone();other.society_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("cold-mountain".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
#[test]fn mswm03_opening_privacy_extra_card_and_no_market_five(){for markets in [0,3]{let(mut g,_)=constructed(1,markets);if markets>0{assert!(g.players[0].hand.is_empty());let p=g.pending.as_ref().unwrap();assert_eq!(p.choice.kind,"mswm03-opening");assert_eq!(p.choice.options.len(),3);for s in 1..4{assert!(g.view(s).pending_choice.is_none());let view=serde_json::to_string(&g.view(s)).unwrap();for o in &g.pending.as_ref().unwrap().choice.options{assert!(!view.contains(&format!("\"{}\"",o.id)));}}restore(&mut g);let id=g.pending.as_ref().unwrap().choice.options[0].id.clone();choose(&mut g,vec![id]);}assert_eq!(g.players[0].hand.len(),if markets>0{6}else{5});assert_eq!(g.players[0].deck.len(),if markets>0{44}else{45});assert_eq!(g.pending.as_ref().unwrap().choice.kind,"mulligan");restore(&mut g);}}
#[test]fn mswm03_opening_missing_duplicate_and_wrong_player_recovery_rejected(){let(g,_)=constructed(2,3);for n in 0..5{let mut bad=g.clone();match n{0=>bad.pending=None,1=>bad.pending.as_mut().unwrap().seat=1,2=>bad.pending.as_mut().unwrap().choice.min=Some(0),3=>bad.effects.push_back(Effect::MSWM03Opening{seat:0}),_=>{bad.players[0].society_zone.used_once_per_game.clear();}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}
#[test]fn mswm03_closed_original_and_counted_offcolor_cap(){let s=crate::society::definition(m::ID).unwrap();assert!(!s.card.supported);assert_eq!((s.starting_hand,s.card.color.as_str()),(5,"黑"));assert!(deck::validate(draft(3)).is_err());for n in [12,13]{let mut d=draft(3);d.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50-n}];for id in ["JC001","JC002","JC004","JC005"]{d.cards.push(catalog::DeckEntry{card_id:id.into(),count:3});}if n==13{d.cards.push(catalog::DeckEntry{card_id:"JC006".into(),count:1});}assert_eq!(validated(d).is_ok(),n==12);}}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn prepared(discarded:&str,index:usize)->serde_json::Value{let(mut g,id,c)=setup();let h=held(&mut g,discarded,0);let mut t=crate::abi112_review_play_tests::Trace::new_preserving_rng(g,format!("mswm03-prepared-discard-{discarded}"),index);t.action(0,action(&id,&h,&c));for _ in 0..32{if t.room.game.stack.is_empty(){break;}t.pass();}assert!(t.room.game.stack.is_empty());assert_eq!(t.room.game.board(&c).is_none(),discarded=="WM063");duplicate(t.value())}
fn natural()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(seed,g,d)=(1..1025).find_map(|seed|{let(g,d)=constructed(seed,3);let mut sample=g.clone();let first=sample.pending.as_ref().unwrap().choice.options[0].id.clone();choose(&mut sample,vec![first]);let h=&sample.players[0].hand;(h.iter().any(|c|c.definition=="JC084")&&h.iter().any(|c|c.definition=="WM057")&&h.iter().any(|c|c.definition=="JC102")&&h.iter().filter(|c|catalog::card(&c.definition).subtypes.iter().any(|s|s=="罪犯")).count()>=4).then_some((seed,g,d))}).expect("bounded legal six including searched market");let mut t=Trace::new_preserving_rng(g,"mswm03-natural-search-market-criminal-hide".into(),7300);let mut society=false;let mut market=false;let mut paid_role=None;
 for _ in 0..850{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue;}if society&&market&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}let g=&t.room.game;let legal=g.legal_actions(0);let pick=if !society{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(m::KEY)&&a.action.cost_selected.as_ref().is_some_and(|ids|g.players[0].hand.iter().any(|c|c.id==ids[0]&&catalog::card(&c.definition).subtypes.iter().any(|s|s=="罪犯"))))}else{None}.or_else(||if !market{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::wm063::DRAW))}else{None}).or_else(||if !g.attachments.iter().any(|a|a.card.definition=="WM063"){legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&c.definition=="WM063")))}else{None}).or_else(||if !society&&!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.controller==0&&c.definition=="JC084"&&!c.face_down){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&c.definition=="JC084")))}else{None}).or_else(||if g.players[0].assets.len()<3{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|c.id==*id&&matches!(c.definition.as_str(),"JC125"|"WM057"))))}else{None});
 if let Some(a)=pick{let a=a.action.clone();if a.ability_id.as_deref()==Some(m::KEY){society=true;paid_role=Some(a.cost_selected.as_ref().unwrap()[1].clone());}if a.ability_id.as_deref()==Some(crate::wm063::DRAW){market=true;}t.action(0,a);}else{t.pass();}}
 assert!(society&&market&&t.room.game.stack.is_empty()&&t.room.game.pending.is_none());assert!(t.room.game.board(paid_role.as_deref().unwrap()).is_none());assert!(t.room.game.regions.iter().flat_map(|r|&r.cards).any(|c|c.controller==0&&c.face_down&&c.definition=="JC084"));assert!(t.room.game.attachments.iter().any(|a|a.card.definition=="WM063"));let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true,"openingSearchIncluded":true});duplicate(v)
}
#[test]fn mswm03_native_room_export(){use sha2::{Digest,Sha256};let cases=vec![natural(),prepared("WM063",7301),prepared("JC125",7302)];let mut b=crate::shoggoth_tests::shoggoth_source_bindings();for(n,bytes)in[("rust-game/src/mswm03.rs",include_bytes!("mswm03.rs").as_slice()),("rust-game/src/mswm03_tests.rs",include_bytes!("mswm03_tests.rs").as_slice()),("rust-game/src/wm063.rs",include_bytes!("wm063.rs").as_slice())]{b["files"].as_object_mut().unwrap().insert(n.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}if let Ok(path)=std::env::var("MSWM03_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":b,"cases":cases})).unwrap()).unwrap();}}
#[test]fn mswm03_actual_tattoo_granted_criminal_cost_survives_response_loss(){let(mut g,id,_)=setup();fund(&mut g,0,"WM057",8);let role=field(&mut g,"JC125",0);let tattoo=attach(&mut g,"WM064",&role);assert!(g.current_subtypes(g.board(&role).unwrap().1).iter().any(|s|s=="罪犯"));let h=held(&mut g,"WM063",0);let legal=g.legal_actions(0).into_iter().find(|a|a.action==action(&id,&h,&role)).unwrap();assert!(legal.label.contains(&h)&&legal.label.contains(&role));act(&mut g,0,legal.action);g.remove_dead(&tattoo,RemovalCause::Destroy);g.drive().unwrap();restore(&mut g);pass_top(&mut g);assert!(g.board(&role).is_none());assert!(g.regions[0].cards.iter().any(|c|c.definition=="JC125"&&c.face_down&&c.exhausted));}
